class ApiError extends Error { constructor(message, data) { super(message); this.data = data; } }
async function api(url, options = {}) {
  const response = await fetch(url, { headers: { 'content-type': 'application/json', ...(options.headers || {}) }, ...options });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new ApiError(data.error || `Request failed (${response.status})`, data);
  return data;
}
async function streamApi(url, options, onProgress) {
  const response = await fetch(url, { headers: { 'content-type': 'application/json' }, ...options });
  if (!response.ok || !response.body) { const data = await response.json().catch(() => ({})); throw new ApiError(data.error || `Request failed (${response.status})`, data); }
  const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = ''; let result;
  while (true) {
    const { value, done } = await reader.read(); buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
    const blocks = buffer.split('\n\n'); buffer = blocks.pop() || '';
    for (const block of blocks) {
      const event = block.match(/^event: (.+)$/m)?.[1]; const raw = block.match(/^data: (.+)$/m)?.[1]; if (!raw) continue;
      const data = JSON.parse(raw); if (event === 'progress') onProgress(data); if (event === 'error') throw new ApiError(data.error, data); if (event === 'result') result = data;
    }
    if (done) break;
  }
  return result;
}
function notify(message, error = false, action) {
  const toast = document.createElement('div'); toast.className = `toast${error ? ' error' : ''}`; toast.append(document.createTextNode(message));
  if (action) { const button = document.createElement('button'); button.textContent = action.label; button.onclick = () => { action.run(); toast.remove(); }; toast.append(button); }
  $('#toasts').append(toast); setTimeout(() => toast.remove(), 5500); $('#status').textContent = message; $('#status').classList.toggle('error', error); clearTimeout(notify.timer); notify.timer = setTimeout(() => { $('#status').textContent = ''; }, 4500);
}
async function perform(action, button) {
  try { if (button) { button.disabled = true; button.classList.add('loading'); button.setAttribute('aria-busy','true'); } return await action(); }
  catch (error) { const llm = /LLM|Ollama|AI request|connection/i.test(error.message); notify(error.message, true, llm ? { label: t('fixSettings'), run: openSettings } : null); }
  finally { if (button) { button.disabled = false; button.classList.remove('loading'); button.removeAttribute('aria-busy'); } }
}
function escapeHtml(value = '') { return String(value).replace(/[&<>'"]/g, (char) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' })[char]); }

function duration(seconds) { const minutes = Math.max(1, Math.round(seconds / 60)); return state.language === 'es' ? `unos ${minutes} min` : `about ${minutes} min`; }
async function confirmEstimate(kind, projectId = state.current?.id) {
  const path = projectId ? `/api/projects/${projectId}/estimate?kind=${encodeURIComponent(kind)}` : `/api/estimate?kind=${encodeURIComponent(kind)}`;
  const { estimate } = await api(path);
  if (!estimate.warning) return true;
  const source = estimate.measured ? (state.language === 'es' ? `medido a ${estimate.tokensPerSecond} tokens/s` : `measured at ${estimate.tokensPerSecond} tokens/s`) : (state.language === 'es' ? `estimado a ${estimate.tokensPerSecond} tokens/s` : `estimated at ${estimate.tokensPerSecond} tokens/s`);
  const message = state.language === 'es' ? `Este trabajo puede tardar ${duration(estimate.totalSeconds)} (${source}). Un modelo más rápido o un proveedor en la nube tardará menos. ¿Continuar?` : `This may take ${duration(estimate.totalSeconds)} (${source}). A faster model or cloud provider will finish sooner. Continue?`;
  return confirm(message);
}

let jobRefreshTimer;
function scheduleJobRefresh(job) {
  clearTimeout(jobRefreshTimer); jobRefreshTimer = setTimeout(() => perform(async () => {
    if (!state.current || state.current.id !== job.projectId) return;
    if (job.kind === 'onboarding' && job.status === 'done') { localStorage.removeItem('opencmoWizard'); localStorage.removeItem('opencmoWizardSkipped'); $('#wizard').hidden = true; await refreshProjects(job.projectId); return; }
    if (job.kind === 'strategy' && job.status === 'done') { state.projects = (await api('/api/projects')).projects; state.current = state.projects.find((project) => project.id === job.projectId); renderProjects(); renderStrategy(); }
    await loadDrafts(); await loadDashboard();
  }), 250);
}
function updateWizardFromJob(job) {
  if (job.kind !== 'onboarding' || $('#wizard').hidden) return;
  const stage = job.payload?.stage; const order = ['health','strategy','drafts']; const current = Math.max(0, order.indexOf(stage));
  $$('#wizard-progress > div').forEach((row,index) => { row.classList.toggle('working', job.status === 'running' && index === current); row.classList.toggle('done', job.status === 'done' || index < current); if (index === current) row.querySelector('small').textContent = job.status === 'failed' ? job.error : job.message; });
}
function renderJobChip() {
  const chip = $('#job-chip'); const job = state.jobs.find((item) => ['running','queued'].includes(item.status)) || state.jobs.find((item) => item.status === 'failed');
  if (!job) { chip.hidden = true; return; }
  chip.hidden = false; chip.className = `job-chip ${job.status}`; const progress = job.total > 1 && (job.progress || /Writing|Escribiendo/.test(job.message)) ? ` ${job.progress}/${job.total}` : '';
  chip.querySelector('strong').textContent = `${job.message}${progress}`; const button = chip.querySelector('.job-action'); button.textContent = job.status === 'failed' ? t('retry') : t('cancel');
  button.onclick = () => perform(async () => { const route = job.status === 'failed' ? 'retry' : 'cancel'; const data = await api(`/api/jobs/${job.id}/${route}`, { method:'POST', body:'{}' }); receiveJob(data.job); }, button);
}
function receiveJob(job, initial = false) {
  const previous = state.jobStatuses.get(job.id); state.jobStatuses.set(job.id, job.status);
  state.jobs = [job, ...state.jobs.filter((item) => item.id !== job.id)].sort((a,b) => b.createdAt.localeCompare(a.createdAt)); renderJobChip(); updateWizardFromJob(job);
  if (!initial && ['month-plan','draft-body'].includes(job.kind) && ['running','done','failed','cancelled'].includes(job.status)) scheduleJobRefresh(job);
  if (!initial && job.status === 'done' && previous !== 'done') { notify(job.kind === 'month-plan' ? t('monthReady') : job.kind === 'strategy' ? t('strategyReady') : t('done')); scheduleJobRefresh(job); }
  if (!initial && job.status === 'failed' && previous !== 'failed') notify(job.error || job.message, true);
}
function connectJobStream(projectId) {
  state.jobSource?.close(); state.jobs = []; state.jobStatuses.clear(); renderJobChip();
  const source = new EventSource(`/api/jobs/stream?project=${encodeURIComponent(projectId)}`); state.jobSource = source;
  source.addEventListener('jobs', (event) => { const data = JSON.parse(event.data); state.jobs = data.jobs; data.jobs.forEach((job) => state.jobStatuses.set(job.id, job.status)); renderJobChip(); data.jobs.forEach(updateWizardFromJob); });
  source.addEventListener('job', (event) => receiveJob(JSON.parse(event.data).job));
  source.addEventListener('token', (event) => { const data = JSON.parse(event.data); if (!state.current || data.job.projectId !== state.current.id || !['strategy','onboarding'].includes(data.job.kind)) return; if (!state.streamedJobs.has(data.job.id)) { state.streamedJobs.add(data.job.id); $('#strategy-content').textContent = ''; $('#strategy-content').classList.remove('muted'); } $('#strategy-content').textContent += data.token; });
}

