const viewNames = { today:['Today','Hoy'], strategy:['Strategy','Estrategia'], knowledge:['Knowledge','Conocimiento'], agents:['Agents','Agentes'], inbox:['Inbox','Bandeja'], calendar:['Calendar','Calendario'], policy:['Rules','Reglas'] };
function switchView(view) {
  if (state.current) { $('#workspace').hidden=false; $('#agency-overview').hidden=true; $('#empty').hidden=true; $('#workspace-language').hidden=false; $('#project-title').textContent=state.current.name; }
  $$('.tab,.panel').forEach((element) => element.classList.remove('active'));
  $(`[data-tab="${view}"]`)?.classList.add('active'); $(`#${view}`)?.classList.add('active');
  $$('[data-nav-tab]').forEach((button) => button.classList.toggle('active', button.dataset.navTab === view));
  $('#agency-overview-button').classList.remove('active');
  $('#breadcrumb-view').textContent = viewNames[view]?.[state.language === 'es' ? 1 : 0] || view;
  document.title = `${viewNames[view]?.[state.language === 'es' ? 1 : 0] || view} — OpenCMO`;
  document.body.classList.remove('nav-open');
}

async function load() {
  const [projectData, agentData, connectorData, settingsData, visibilityData] = await Promise.all([api('/api/projects'), api('/api/agents'), api('/api/connectors'), api('/api/settings'), api('/api/visibility/providers')]);
  state.projects = projectData.projects; state.agents = agentData.agents; state.connectors = connectorData.connectors; state.language = settingsData.settings.uiLanguage === 'es' ? 'es' : settingsData.settings.uiLanguage === 'en' ? 'en' : state.language;
  state.visibilityProviders = visibilityData.providers; state.visibilitySelected = visibilityData.selected; state.visibilityKeySaved = visibilityData.keySaved; renderVisibilityProviders();
  applyLanguage(); renderProjects(); renderAgents();
  if (state.projects.length > 1) await showAgencyOverview();
  else if (state.projects.length) await selectProject(state.projects[0].id);
  else { $('#empty').hidden = false; if (!localStorage.getItem('opencmoWizardSkipped')) showWizard(); }
}
function renderProjects() {
  const query = ($('#project-search')?.value || '').trim().toLowerCase(); const projects = state.projects.filter((project) => project.name.toLowerCase().includes(query));
  $('#projects').innerHTML = projects.map((p) => `<button data-project="${p.id}" class="${state.current?.id === p.id ? 'active' : ''}">${p.isDemo ? '<span class="demo-dot">Demo</span> ' : ''}${escapeHtml(p.name)}</button>`).join('') || `<p class="local-note">${state.language === 'es' ? 'Sin resultados' : 'No matches'}</p>`;
  $$('[data-project]').forEach((button) => button.onclick = () => selectProject(button.dataset.project));
}
async function selectProject(id) {
  state.current = state.projects.find((project) => project.id === id); if (!state.current) return;
  state.language = state.current.language || state.language; applyLanguage(); $('#workspace-language').hidden = false; $('#empty').hidden = true; $('#workspace').hidden = false; $('#project-title').textContent = state.current.name;
  $('#demo-badge').hidden = !state.current.isDemo; $('#delete-demo').hidden = !state.current.isDemo; renderStrategy();
  renderProjects(); renderAgents(); switchView('today');
  $('#agency-overview').hidden = true; await Promise.all([loadDrafts(), loadGeoHistory(), loadKnowledge(), loadPolicy(), loadSearchOpportunities()]); await loadDashboard(); connectJobStream(id);
  $('#competitor-urls').value = (state.current.competitors || []).join('\n');
}
async function refreshProjects(selectId) { state.projects = (await api('/api/projects')).projects; renderProjects(); if (selectId) await selectProject(selectId); }

