  const geo = state.geoHistory.at(-1); const visibility = geo ? Math.round((geo.visible / Math.max(1, geo.total)) * 100) : '—'; const scheduledCount = state.allDrafts.filter((draft) => draft.scheduledAt).length;
  const activity = [...state.allDrafts].sort((a,b) => String(b.updatedAt || b.createdAt).localeCompare(String(a.updatedAt || a.createdAt))).slice(0,4);
  $('#today-dashboard').innerHTML = `<div class="kpi-grid"><article class="card kpi"><div class="kpi-top"><span>${t('siteScore')}</span>${icon('report')}</div><strong class="kpi-value">${score}${health ? '<small>/100</small>' : ''}</strong><p class="kpi-meta">${escapeHtml(trend)}</p></article><article class="card kpi"><div class="kpi-top"><span>${state.language === 'es' ? 'Visibilidad IA' : 'AI visibility'}</span>${icon('spark')}</div><strong class="kpi-value">${visibility}${geo ? '%' : ''}</strong><p class="kpi-meta">${geo ? `${geo.visible}/${geo.total} ${state.language === 'es' ? 'respuestas' : 'answers'}` : (state.language === 'es' ? 'Sin medición' : 'No measurement yet')}</p></article><article class="card kpi"><div class="kpi-top"><span>${t('pending')}</span>${icon('inbox')}</div><strong class="kpi-value">${data.pending}</strong><p class="kpi-meta">${state.language === 'es' ? 'Esperando revisión' : 'Awaiting your review'}</p></article><article class="card kpi"><div class="kpi-top"><span>${t('scheduled')}</span>${icon('calendar')}</div><strong class="kpi-value">${scheduledCount}</strong><p class="kpi-meta">${state.language === 'es' ? 'En el calendario' : 'On the calendar'}</p></article></div><div class="dashboard-section"><h3>${t('nextActions')}</h3><div class="next-actions">${actions}</div></div><div class="today-side"><article class="card health-card"><div class="score-ring" style="--score:${health?.score || 0}"><strong>${score}</strong><small>/100</small></div><div><h3>${t('siteScore')}</h3><p>${escapeHtml(trend)}</p></div>${healthButton}${report}</article><article class="card schedule-card"><h3>${t('week')}</h3><ul>${schedule}</ul><button class="secondary small" data-tab-go="calendar">${t('calendar')}</button></article><article class="card brief-card"><h3>${t('lastBrief')}</h3>${data.lastBrief ? `<strong>${escapeHtml(data.lastBrief.title)}</strong><p>${escapeHtml(data.lastBrief.body.slice(0, 150))}</p><button class="secondary small" data-tab-go="inbox">${t('review')}</button>` : `<p>${t('noBrief')}</p><button class="secondary small" data-brief>${t('createBrief')}</button>`}</article><article class="card"><h3>${state.language === 'es' ? 'Actividad reciente' : 'Recent activity'}</h3><ul class="activity-timeline">${activity.length ? activity.map((draft) => `<li><strong>${escapeHtml(draft.title)}</strong><br>${t(draft.status)}</li>`).join('') : `<li>${t('noActivity')}</li>`}</ul></article></div>`;
