async function generateMonth(button) { await perform(async () => { if (!await confirmEstimate('month-plan')) return; const data = await api(`/api/projects/${state.current.id}/month-plan`, { method:'POST', body:'{}' }); if (data.job) receiveJob(data.job); else notify(t('monthReady')); await Promise.all([loadDrafts(),loadPolicy()]); await loadDashboard(); switchView('calendar'); }, button); }

