  $$('[data-agent]').forEach((button) => button.onclick = () => { state.selectedAgent = button.dataset.agent; $('#selected-agent').textContent = names[state.selectedAgent]?.[state.language === 'es' ? 1 : 0] || state.selectedAgent; $('#geo-options').hidden = state.selectedAgent !== 'geo'; renderAgents(); });
