  help.textContent = state.language === 'es' ? `${provider.name}: crea una clave en ${provider.site} (${provider.section}). ${saved ? 'Ya hay una clave guardada para este proveedor.' : `Suele empezar por ${provider.prefix}`}` : `${provider.name}: create a key at ${provider.site} (${provider.section}). ${saved ? 'A key is already saved for this provider.' : `It usually starts with ${provider.prefix}`}`;
