  box.innerHTML = `<div class="visibility-score"><strong>${result.percent}%</strong><div><h3>${escapeHtml(result.provider)}</h3><p>${result.visible}/${result.total} ${state.language === 'es' ? 'respuestas mencionan o citan la marca. Es una muestra direccional, no una medida de ranking.' : 'answers mention or cite the brand. This is a directional sample, not a ranking measurement.'}</p><div class="visibility-sources">${topSources}${topCompetitors}</div></div></div><div class="visibility-list">${answers}</div>`;
