  $('#approval-list').innerHTML = data.approvals.length ? data.approvals.map((approval) => `<article class="card approval-item"><div><strong>${escapeHtml(approval.summary)}</strong><p class="muted">${escapeHtml(approval.agent)}</p></div><div><button class="primary" data-approval="${approval.id}" data-decision="approve">${t('approve')}</button> <button class="danger" data-approval="${approval.id}" data-decision="reject">${t('reject')}</button></div></article>`).join('') : `<div class="card empty-list">${t('noApprovals')}</div>`;
  $('#activity-list').innerHTML = data.activity.length ? data.activity.map((entry) => `<p><strong>${escapeHtml(actionName(entry.action))}</strong> · ${escapeHtml(decisionName(entry.decision))} <small>${escapeHtml(entry.actor || '')} · ${new Date(entry.at).toLocaleString()}</small></p>`).join('') : `<p class="muted">${t('noActivity')}</p>`;
