function draftEditor(draft) {
  const quality = draft.quality || { count:draft.body.length, limit:null, violations:[], cliches:[] }; const sources = Array.isArray(draft.metadata.sources) ? draft.metadata.sources : []; const needsBody = Boolean(draft.metadata.needsBody);
  const writing = needsBody ? `<div class="writing-state">${draft.metadata.writing ? '<span class="spinner"></span>' : ''}<span>${t('writing')}</span><button class="secondary write-now">${t('writeNow')}</button></div>` : '';
  const feedback = needsBody ? '' : `<div class="feedback"><input aria-label="${t('regenerate')}" placeholder="${state.language === 'es' ? 'Ej.: Más específico, menos promocional' : 'E.g. Make it more specific and less promotional'}"><button class="secondary regenerate">${t('regenerate')}</button>${quality.cliches.length ? `<button class="secondary rewrite">${t('rewrite')}</button>` : ''}</div>`;
  const actions = needsBody ? '' : `<div class="actions"><button class="secondary copy">${t('copy')}</button>${draft.status !== 'published' ? `<button class="secondary save">${t('save')}</button>` : ''}${draft.status === 'pending' || draft.status === 'rejected' ? `<button class="primary approve">${t('approve')}</button>` : ''}${draft.status === 'pending' || draft.status === 'approved' ? `<button class="danger reject">${t('reject')}</button>` : ''}${draft.status === 'rejected' ? `<button class="secondary undo">${t('undo')}</button>` : ''}${draft.status === 'approved' ? `<select class="connector">${connectorOptions()}</select><button class="primary publish">${t('publish')}</button><input class="schedule-date" type="datetime-local" aria-label="${t('schedule')}"><button class="secondary schedule">${t('schedule')}</button>` : ''}</div>`;
  return `<article class="draft ${needsBody ? 'writing' : ''}" tabindex="0" data-draft="${draft.id}"><div class="draft-head"><div class="draft-title"><small>${escapeHtml(draft.channel)} · ${escapeHtml(draft.agentId)}</small><input class="title-input" title="${escapeHtml(draft.title)}" value="${escapeHtml(draft.title)}" ${draft.status === 'published' ? 'disabled' : ''}></div><span class="badge ${draft.status}">${needsBody ? t('writing') : t(draft.status)}</span></div>${writing}<textarea ${draft.status === 'published' ? 'disabled' : ''} ${quality.limit ? `maxlength="${quality.limit}"` : ''}>${escapeHtml(draft.body)}</textarea><div class="quality-row">${quality.cliches.length ? `<span class="cliche">${icon('alert')} ${escapeHtml(quality.cliches.join(', '))}</span>` : `<span>${icon('check')} ${state.language === 'es' ? 'Sin frases artificiales detectadas' : 'No AI-sounding phrases detected'}</span>`}<span class="counter ${quality.violations.length ? 'bad' : ''}">${quality.count}${quality.limit ? ` / ${quality.limit}` : ''} ${t('chars')}</span></div><details class="sources"><summary>${t('sources')} (${sources.length})</summary>${sources.length ? sources.map((source) => `<span class="source-chip">${escapeHtml(source.label)} · ${escapeHtml(source.title)}</span>`).join('') : `<p class="muted">${t('noSources')}</p>`}</details>${feedback}${actions}${draft.scheduledAt ? `<p class="scheduled">${t('scheduled')} ${new Date(draft.scheduledAt).toLocaleString()}</p>` : draft.metadata.plannedAt ? `<p class="planned">${t('planned')} ${new Date(draft.metadata.plannedAt).toLocaleString()}</p>` : ''}</article>`;
}
function bindDraft(card, draft) {
  const textarea = card.querySelector('textarea'); const counter = card.querySelector('.counter'); textarea?.addEventListener('input', () => { counter.textContent = `${textarea.value.length}${textarea.maxLength > 0 ? ` / ${textarea.maxLength}` : ''} ${t('chars')}`; counter.classList.toggle('bad', textarea.maxLength > 0 && textarea.value.length > textarea.maxLength); });
  card.querySelector('.copy')?.addEventListener('click', () => perform(async () => { await navigator.clipboard.writeText(textarea.value); notify(t('copied')); }));
  card.querySelector('.write-now')?.addEventListener('click', (event) => perform(async () => { const data = await api(`/api/drafts/${draft.id}/write-now`, { method:'POST', body:'{}' }); receiveJob(data.job); }, event.currentTarget));
  card.querySelector('.save')?.addEventListener('click', (event) => perform(async () => { await api(`/api/drafts/${draft.id}`, { method:'PATCH', body:JSON.stringify({ title:card.querySelector('.title-input').value, body:textarea.value }) }); notify(t('draftSaved')); await loadDrafts(); }, event.currentTarget));
  card.querySelector('.approve')?.addEventListener('click', () => transition(draft.id,'approve')); card.querySelector('.reject')?.addEventListener('click', () => transition(draft.id,'reject')); card.querySelector('.undo')?.addEventListener('click', () => undoReject(draft.id));
  const regenerate = (feedback, button) => perform(async () => { await api(`/api/drafts/${draft.id}/regenerate`, { method:'POST', body:JSON.stringify({ feedback }) }); await loadDrafts(); }, button);
  card.querySelector('.regenerate')?.addEventListener('click', (event) => regenerate(card.querySelector('.feedback input').value, event.currentTarget)); card.querySelector('.rewrite')?.addEventListener('click', (event) => regenerate('', event.currentTarget));
  card.querySelector('.publish')?.addEventListener('click', (event) => perform(async () => { const connector = card.querySelector('.connector').value; if (!connector) throw new Error(t('chooseConnector')); await api(`/api/drafts/${draft.id}/publish`, { method:'POST', body:JSON.stringify({ connector }) }); notify(t('draftPublished')); await loadDrafts(); }, event.currentTarget));
  card.querySelector('.schedule')?.addEventListener('click', (event) => perform(async () => { const connector = card.querySelector('.connector').value; const date = card.querySelector('.schedule-date').value; if (!connector || !date) throw new Error(state.language === 'es' ? 'Elige conector y fecha' : 'Choose a connector and date'); await api(`/api/drafts/${draft.id}/schedule`, { method:'POST', body:JSON.stringify({ connector, scheduledAt:new Date(date).toISOString() }) }); notify(t('draftScheduled')); await loadDrafts(); }, event.currentTarget));
}
async function transition(id, action) { await perform(async () => { await api(`/api/drafts/${id}/${action}`, { method:'POST' }); if (action === 'reject') notify(t('draftRejected'), false, { label:t('undo'), run:() => undoReject(id) }); else notify(t('draftApproved')); await Promise.all([loadDrafts(),loadDashboard()]); }); }
