function dateKey(date) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`; }
function renderCalendar() {
  const locale = state.language === 'es' ? 'es-ES' : 'en-US'; const cursor = new Date(state.calendar.date); cursor.setHours(12,0,0,0); let start;
  if (state.calendar.view === 'week') { start = new Date(cursor); start.setDate(cursor.getDate() - ((cursor.getDay()+6)%7)); }
  else { const first = new Date(cursor.getFullYear(),cursor.getMonth(),1,12); start = new Date(first); start.setDate(first.getDate() - ((first.getDay()+6)%7)); }
  const count = state.calendar.view === 'week' ? 7 : 42; const days = Array.from({length:count},(_,index) => { const date = new Date(start); date.setDate(start.getDate()+index); return date; });
  const byDay = new Map(); state.allDrafts.filter((draft) => draft.scheduledAt || draft.metadata.plannedAt).forEach((draft) => { const key = dateKey(new Date(draft.scheduledAt || draft.metadata.plannedAt)); byDay.set(key,[...(byDay.get(key)||[]),draft]); });
  const label = state.calendar.view === 'week' ? `${days[0].toLocaleDateString(locale,{month:'short',day:'numeric'})} – ${days.at(-1).toLocaleDateString(locale,{month:'short',day:'numeric',year:'numeric'})}` : cursor.toLocaleDateString(locale,{month:'long',year:'numeric'}); $('#calendar-label').textContent = label;
  const weekdays = days.slice(0,7).map((date) => `<div class="calendar-weekday">${date.toLocaleDateString(locale,{weekday:'short'})}</div>`).join(''); const today = dateKey(new Date());
  $('#calendar-list').classList.toggle('week-view',state.calendar.view === 'week'); $('#calendar-list').innerHTML = `${weekdays}${days.map((date) => { const key=dateKey(date); const items=byDay.get(key)||[]; const outside=state.calendar.view==='month'&&date.getMonth()!==cursor.getMonth(); return `<div class="calendar-day ${outside?'outside':''} ${key===today?'today':''}" data-calendar-date="${key}"><button class="calendar-date" aria-label="${state.language === 'es' ? 'Programar para' : 'Schedule for'} ${date.toLocaleDateString(locale)}">${date.getDate()}</button>${items.slice(0,3).map((draft) => `<button class="calendar-chip ${draft.status}" data-calendar-draft="${draft.id}" title="${escapeHtml(draft.title)}">${escapeHtml(draft.title)}</button>`).join('')}${items.length>3?`<span class="calendar-more">+${items.length-3} ${state.language==='es'?'más':'more'}</span>`:''}</div>`; }).join('')}`;
  $$('.calendar-date').forEach((button) => button.onclick = () => openCalendarSchedule(button.closest('[data-calendar-date]').dataset.calendarDate)); $$('[data-calendar-draft]').forEach((button) => button.onclick = () => { $('#draft-filter').value=''; $('#draft-search').value=''; state.drafts=state.allDrafts; state.activeDraftId=button.dataset.calendarDraft; switchView('inbox'); renderDrafts(); });
}
function openCalendarSchedule(day) { const drafts=state.allDrafts.filter((draft)=>draft.status==='approved'&&!draft.metadata.needsBody&&!draft.scheduledAt); if(!drafts.length) return notify(state.language==='es'?'No hay borradores aprobados sin programar.':'There are no unscheduled approved drafts.',true); const form=$('#calendar-form'); form.elements.draftId.innerHTML=drafts.map((draft)=>`<option value="${draft.id}">${escapeHtml(draft.title)}</option>`).join(''); form.elements.connector.innerHTML=connectorOptions(); form.elements.scheduledAt.value=`${day}T09:00`; $('#calendar-dialog').showModal(); }

