$('#mobile-nav-toggle').onclick = () => document.body.classList.add('nav-open'); $('#close-mobile-nav').onclick = () => document.body.classList.remove('nav-open');
$$('[data-nav-tab]').forEach((button) => button.onclick = () => state.current ? switchView(button.dataset.navTab) : state.projects[0] ? perform(async()=>{await selectProject(state.projects[0].id);switchView(button.dataset.navTab);}) : undefined);
$('#project-form').onsubmit = (event) => perform(async () => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget)); try { const data = await api('/api/projects', { method:'POST', body:JSON.stringify(body) }); $('#project-dialog').close(); event.currentTarget.reset(); await refreshProjects(data.project.id); if (state.pendingProfileText) { await api(`/api/projects/${data.project.id}/knowledge`, { method:'POST', body:JSON.stringify({ title:'Website profile', source:data.project.url, text:state.pendingProfileText }) }); state.pendingProfileText = ''; } notify(t('projectCreated')); } catch (error) { if (error.data?.code === 'duplicate_project' && confirm(t('duplicate'))) { const merged = await api(`/api/projects/${error.data.project.id}/merge`, { method:'POST', body:JSON.stringify(body) }); $('#project-dialog').close(); event.currentTarget.reset(); await refreshProjects(merged.project.id); return; } throw error; } }, event.submitter);
$$('.tab').forEach((tab) => tab.onclick = () => switchView(tab.dataset.tab));
$('#generate-strategy').onclick = (event) => perform(async () => { if (!await confirmEstimate('strategy')) return; const data = await api(`/api/projects/${state.current.id}/strategy`, { method:'POST', body:'{}' }); $('#strategy-content').textContent = state.language === 'es' ? 'Preparando la estrategia…' : 'Preparing strategy…'; $('#strategy-content').classList.add('muted'); receiveJob(data.job); }, event.currentTarget);
$('#run-form').onsubmit = (event) => perform(async () => { event.preventDefault(); const progress = $('#run-progress'); progress.hidden = false; try { const data = await streamApi(`/api/projects/${state.current.id}/agents/${state.selectedAgent}/run?stream=1`, { method:'POST', body:JSON.stringify({ task:$('#task').value, questionCount:Number($('#question-count').value), questions:$('#geo-questions').value.split('\n').filter(Boolean) }) }, (item) => progress.querySelector('span:last-child').textContent = item.message); $('#task').value = ''; notify(`${data.drafts.length} ${state.language === 'es' ? 'borradores creados' : 'drafts created'}`); switchView('inbox'); await Promise.all([loadDrafts(),loadGeoHistory()]); await loadDashboard(); } finally { progress.hidden = true; } }, event.submitter);
$('#visibility-provider').onchange = () => { renderVisibilityProviderHelp(); const changed = $('#visibility-provider').value !== state.visibilitySelected; $('#visibility-key').placeholder = !changed && state.visibilityKeySaved ? (state.language === 'es' ? 'Clave guardada · deja en blanco para reutilizarla' : 'Key saved · leave blank to reuse') : (state.language === 'es' ? 'Introduce una clave para este proveedor' : 'Enter a key for this provider'); };
$('#visibility-form').onsubmit = (event) => perform(async () => {
  event.preventDefault(); if (!state.current) return;
  const progress = $('#visibility-progress'); progress.hidden = false;
  try {
    const provider = $('#visibility-provider').value; const apiKey = $('#visibility-key').value;
    const questions = $('#visibility-questions').value.split('\n').map((value) => value.trim()).filter(Boolean);
    const data = await api(`/api/projects/${state.current.id}/ai-visibility`, { method:'POST', body:JSON.stringify({ provider, apiKey, count:Number($('#visibility-count').value), questions }) });
    state.visibilitySelected = provider; state.visibilityKeySaved = true; $('#visibility-key').value = ''; renderVisibilityProviders(); renderVisibilityResult(data.result);
    await Promise.all([loadGeoHistory(), loadDashboard()]); notify(state.language === 'es' ? 'Comprobación de visibilidad terminada' : 'Visibility check complete');
  } finally { progress.hidden = true; }
}, event.submitter);
$('#draft-filter').onchange = () => perform(loadDrafts); $('#select-all').onclick = () => { $$('.list-pick:not(:disabled)').forEach((box) => { box.checked = true; state.selected.add(box.closest('[data-open-draft]').dataset.openDraft); }); };
async function bulk(action) { if (!state.selected.size) return notify(t('selectOne'),true); await perform(async () => { await api('/api/drafts/bulk', { method:'POST', body:JSON.stringify({ ids:[...state.selected], action }) }); await Promise.all([loadDrafts(),loadDashboard()]); }); } $('#bulk-approve').onclick = () => bulk('approve'); $('#bulk-reject').onclick = () => bulk('reject');
$('#generate-month').onclick = (event) => generateMonth(event.currentTarget); $('#delete-demo').onclick = (event) => perform(async () => { if (!confirm(t('deleteDemoConfirm'))) return; await api(`/api/projects/${state.current.id}`, { method:'DELETE' }); state.current = null; await refreshProjects(); if (state.projects.length) await selectProject(state.projects[0].id); else { $('#workspace').hidden = true; $('#empty').hidden = false; } }, event.currentTarget);
$('#export-report').onclick = () => { if (state.current) window.location.assign(`/api/projects/${state.current.id}/report`); };
$('#calendar-month-view').onclick = () => { state.calendar.view='month'; $('#calendar-month-view').classList.add('active'); $('#calendar-week-view').classList.remove('active'); renderCalendar(); }; $('#calendar-week-view').onclick = () => { state.calendar.view='week'; $('#calendar-week-view').classList.add('active'); $('#calendar-month-view').classList.remove('active'); renderCalendar(); }; $('#calendar-today').onclick = () => { state.calendar.date=new Date(); renderCalendar(); }; $('#calendar-prev').onclick = () => { const date=new Date(state.calendar.date); if(state.calendar.view==='month'){date.setDate(1);date.setMonth(date.getMonth()-1);}else date.setDate(date.getDate()-7); state.calendar.date=date; renderCalendar(); }; $('#calendar-next').onclick = () => { const date=new Date(state.calendar.date); if(state.calendar.view==='month'){date.setDate(1);date.setMonth(date.getMonth()+1);}else date.setDate(date.getDate()+7); state.calendar.date=date; renderCalendar(); };
$('#calendar-form').onsubmit = (event) => perform(async () => { event.preventDefault(); const values=Object.fromEntries(new FormData(event.currentTarget)); await api(`/api/drafts/${values.draftId}/schedule`,{method:'POST',body:JSON.stringify({connector:values.connector,scheduledAt:new Date(values.scheduledAt).toISOString()})}); $('#calendar-dialog').close(); notify(t('draftScheduled')); await loadDrafts(); await loadDashboard(); },event.submitter); $('[data-close-calendar]').onclick=()=>$('#calendar-dialog').close();
$('#gsc-file').onchange = (event) => perform(async () => { const file = event.target.files[0]; if (!file) return; const data = await api(`/api/projects/${state.current.id}/search-console`, { method:'POST', body:JSON.stringify({ csv:await file.text() }) }); notify(state.language === 'es' ? `${data.opportunities.length} oportunidades encontradas` : `${data.opportunities.length} opportunities found`); await loadSearchOpportunities(); event.target.value = ''; });
$('#competitor-form').onsubmit = (event) => perform(async () => { event.preventDefault(); const urls = $('#competitor-urls').value.split('\n').map((value) => value.trim()).filter(Boolean); if (urls.length > 5) throw new Error(state.language === 'es' ? 'Añade un máximo de cinco competidores' : 'Add no more than five competitors'); const data = await api(`/api/projects/${state.current.id}/competitors/audit`, { method:'POST', body:JSON.stringify({ urls }) }); state.current.competitors = urls; renderCompetitors(data); }, event.submitter);
$('#workspace-language').onchange = (event) => perform(async () => { const data = await api(`/api/projects/${state.current.id}`, { method:'PATCH', body:JSON.stringify({ language:event.target.value }) }); state.current = data.project; state.projects = state.projects.map((project) => project.id === data.project.id ? data.project : project); state.language = data.project.language; applyLanguage(); renderAgents(); await Promise.all([loadDrafts(),loadDashboard(),loadKnowledge(),loadPolicy()]); });

async function openSettings() { await perform(async () => { const data = await api('/api/settings'); const form = $('#settings-form'); Object.entries(data.settings).forEach(([key,value]) => { if (!form.elements[key]) return; if (form.elements[key].type === 'checkbox') form.elements[key].checked = value === '1'; else form.elements[key].value = value; }); renderSettingsMeta(data); $('#settings-dialog').showModal(); }); }
$('#open-settings').onclick = openSettings; $('[data-close-settings]').onclick = () => $('#settings-dialog').close();
function settingsPayload() { const form = $('#settings-form'); const result = Object.fromEntries(new FormData(form)); ['brandingPoweredBy','ragEmbeddings','briefsEnabled','briefTelegram','hindsightEnabled'].forEach((name) => result[name] = form.elements[name].checked ? '1' : '0'); return result; }
$('#settings-form').onsubmit = (event) => perform(async () => { event.preventDefault(); const body = settingsPayload(); await api('/api/settings', { method:'PUT', body:JSON.stringify(body) }); state.language = body.uiLanguage === 'es' ? 'es' : 'en'; applyLanguage(); state.connectors = (await api('/api/connectors')).connectors; $('#settings-dialog').close(); notify(t('settingsSaved')); if (state.current) await Promise.all([loadDrafts(),loadDashboard(),loadKnowledge(),loadPolicy()]); }, event.submitter);
$('#test-llm').onclick = (event) => perform(async () => { await api('/api/settings/test-llm', { method:'POST', body:JSON.stringify(settingsPayload()) }); $('.connection-status').classList.add('connected'); $('#connection-label').textContent=state.language==='es'?'Conectada correctamente':'Connected successfully'; notify(t('engineWorks')); }, event.currentTarget);
function renderSettingsMeta(data) { $('#llm-stats').textContent = `${data.llm.calls24h} ${state.language === 'es' ? 'llamadas' : 'calls'} · ${data.llm.errors24h} ${state.language === 'es' ? 'errores' : 'errors'} · ${data.llm.avgMs} ms · ${data.llm.tokensPerSecond || '—'} tok/s`; $('.connection-status').classList.toggle('connected',data.llm.calls24h>data.llm.errors24h); $('#connection-label').textContent=data.llm.calls24h ? (data.llm.errors24h===data.llm.calls24h ? (state.language==='es'?'La última actividad tuvo errores':'Recent activity has errors') : (state.language==='es'?'Actividad correcta en las últimas 24 h':'Healthy activity in the last 24h')) : (state.language==='es'?'Sin probar en esta sesión':'Not tested in this session'); $('#integrity-status').textContent = `${state.language === 'es' ? 'Integridad de la base de datos' : 'Database integrity'}: ${data.integrity}`; $('#backup-list').innerHTML = data.backups.length ? data.backups.map((item) => `<p>${escapeHtml(item.name)} · ${Math.ceil(item.size/1024)} KB <button type="button" class="danger small" data-restore="${escapeHtml(item.name)}">${state.language === 'es' ? 'Restaurar' : 'Restore'}</button></p>`).join('') : `<p class="muted">${state.language === 'es' ? 'Aún no hay copias.' : 'No backups yet.'}</p>`; $$('[data-restore]').forEach((button) => button.onclick = () => perform(async () => { if (!confirm(state.language === 'es' ? '¿Restaurar esta copia al reiniciar? Se guardará una copia de seguridad.' : 'Restore this backup on restart? A safety copy will be kept.')) return; await api(`/api/backups/${encodeURIComponent(button.dataset.restore)}/restore`, { method:'POST' }); notify(state.language === 'es' ? 'Restauración preparada. Reinicia OpenCMO.' : 'Restore staged. Restart OpenCMO.'); })); }
$('#create-backup').onclick = (event) => perform(async () => { await api('/api/backups', { method:'POST' }); renderSettingsMeta(await api('/api/settings')); }, event.currentTarget);
$('#branding-logo-file').onchange = (event) => { const file = event.target.files[0]; if (!file) return; if (file.size > 500000) return notify(state.language === 'es' ? 'El logo debe pesar menos de 500 KB' : 'Logo must be smaller than 500 KB', true); const reader = new FileReader(); reader.onload = () => { $('#settings-form').elements.brandingLogoData.value = String(reader.result || ''); }; reader.readAsDataURL(file); };
$('#profile-site').onclick = (event) => perform(async () => { const form = $('#project-form'); if (!form.elements.url.value) throw new Error(state.language === 'es' ? 'Introduce primero una URL' : 'Enter a website URL first'); const { profile } = await api('/api/onboarding/profile', { method:'POST', body:JSON.stringify({ url:form.elements.url.value }) }); ['name','description','audience','tone'].forEach((key) => { if (profile[key] && !form.elements[key].value) form.elements[key].value = profile[key]; }); state.pendingProfileText = profile.text || ''; notify(t('profileReady')); }, event.currentTarget);
$('#knowledge-file').onchange = async (event) => { if (event.target.files[0]) $('#knowledge-text').value = await event.target.files[0].text(); }; $('#knowledge-form').onsubmit = (event) => perform(async () => { event.preventDefault(); await api(`/api/projects/${state.current.id}/knowledge`, { method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); event.currentTarget.reset(); await loadKnowledge(); }, event.submitter); $('#import-site').onclick = (event) => perform(async () => { await api(`/api/projects/${state.current.id}/knowledge/import-site`, { method:'POST' }); await loadKnowledge(); }, event.currentTarget);
$('#policy-form').onsubmit = (event) => perform(async () => { event.preventDefault(); await api('/api/policy', { method:'PUT', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); await loadPolicy(); }, event.submitter); $('#stop-agents').onclick = (event) => perform(async () => { const paused = event.currentTarget.dataset.paused !== 'true'; await api('/api/agents/stop', { method:'POST', body:JSON.stringify({ paused }) }); await loadPolicy(); }, event.currentTarget);
$('#shortcut-help').onclick = () => $('#shortcut-dialog').showModal(); $('[data-close-shortcuts]').onclick = () => $('#shortcut-dialog').close(); document.addEventListener('keydown', (event) => { if (event.key === '?' && !/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)) return $('#shortcut-dialog').showModal(); if (/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)) return; const card = document.activeElement?.closest?.('.draft'); if (!card) return; if (event.key === 'a') card.querySelector('.approve')?.click(); if (event.key === 'r') card.querySelector('.reject')?.click(); if (event.key === 'e') card.querySelector('textarea')?.focus(); });

load().catch((error) => notify(error.message,true));
